import { useState, useEffect } from "react";
import api from "../api";

export default function AdminDashboard() {
  const [services, setServices] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [users, setUsers] = useState([]);
  const [providers, setProviders] = useState([]);
  const [newService, setNewService] = useState({ name: "", category: "", rating: 0 });
  const [activeTab, setActiveTab] = useState("services");

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const [servicesRes, bookingsRes, usersRes, providersRes] = await Promise.all([
        api.get("/services"),
        api.get("/bookings"),
        api.get("/auth/users"),
        api.get("/auth/providers")
      ]);
      setServices(servicesRes.data);
      setBookings(bookingsRes.data);
      setUsers(usersRes.data);
      setProviders(providersRes.data);
    } catch (err) {
      console.error("Error loading data:", err);
    }
  };

  const handleAddService = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem("token");
      await api.post("/services", newService, {
        headers: { Authorization: `Bearer ${token}` }
      });
      alert("Service added successfully!");
      setNewService({ name: "", category: "", rating: 0 });
      loadData();
    } catch (err) {
      alert("Failed to add service");
    }
  };

  const handleDeleteService = async (serviceId) => {
    try {
      const token = localStorage.getItem("token");
      await api.delete(`/services/${serviceId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      alert("Service deleted successfully!");
      loadData();
    } catch (err) {
      alert("Failed to delete service");
    }
  };

  const handleVerifyProvider = async (providerId) => {
    try {
      await api.put(`/auth/verify-provider/${providerId}`, { verified: true });
      alert("Provider verified successfully!");
      loadData();
    } catch (err) {
      alert("Failed to verify provider");
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h1>Admin Dashboard</h1>
      <p>Welcome, Admin!</p>

      <div style={{ marginBottom: "20px" }}>
        <button 
          onClick={() => setActiveTab("services")}
          style={{ padding: "10px 20px", marginRight: "10px", cursor: "pointer" }}
        >
          Services
        </button>
        <button 
          onClick={() => setActiveTab("bookings")}
          style={{ padding: "10px 20px", marginRight: "10px", cursor: "pointer" }}
        >
          Bookings
        </button>
        <button 
          onClick={() => setActiveTab("users")}
          style={{ padding: "10px 20px", marginRight: "10px", cursor: "pointer" }}
        >
          Users
        </button>
        <button 
          onClick={() => setActiveTab("providers")}
          style={{ padding: "10px 20px", cursor: "pointer" }}
        >
          Providers
        </button>
      </div>

      {activeTab === "services" && (
        <div>
          <h2>Manage Services</h2>
          
          <form onSubmit={handleAddService} style={{ marginBottom: "20px", padding: "15px", border: "1px solid #ccc" }}>
            <h3>Add New Service</h3>
            <div style={{ marginBottom: "10px" }}>
              <input
                type="text"
                placeholder="Service Name"
                value={newService.name}
                onChange={(e) => setNewService({ ...newService, name: e.target.value })}
                required
                style={{ padding: "8px", marginRight: "10px" }}
              />
              <input
                type="text"
                placeholder="Category"
                value={newService.category}
                onChange={(e) => setNewService({ ...newService, category: e.target.value })}
                required
                style={{ padding: "8px", marginRight: "10px" }}
              />
              <input
                type="number"
                placeholder="Rating"
                value={newService.rating}
                onChange={(e) => setNewService({ ...newService, rating: parseFloat(e.target.value) })}
                step="0.1"
                min="0"
                max="5"
                style={{ padding: "8px", marginRight: "10px" }}
              />
              <button type="submit" style={{ padding: "8px 16px", cursor: "pointer" }}>
                Add Service
              </button>
            </div>
          </form>

          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ backgroundColor: "#f0f0f0" }}>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Name</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Category</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Rating</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Action</th>
              </tr>
            </thead>
            <tbody>
              {services.map((service) => (
                <tr key={service._id}>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{service.name}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{service.category}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{service.rating}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>
                    <button 
                      onClick={() => handleDeleteService(service._id)}
                      style={{ padding: "5px 10px", cursor: "pointer", backgroundColor: "#ff4444", color: "white", border: "none" }}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === "bookings" && (
        <div>
          <h2>All Bookings</h2>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ backgroundColor: "#f0f0f0" }}>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Service</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Location</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Status</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Payment</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((booking) => (
                <tr key={booking._id}>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{booking.serviceName}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{booking.location}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{booking.status}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{booking.paymentStatus}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === "users" && (
        <div>
          <h2>All Users</h2>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ backgroundColor: "#f0f0f0" }}>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Name</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Email</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Role</th>
              </tr>
            </thead>
            <tbody>
              {users.map((user) => (
                <tr key={user._id}>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{user.name}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{user.email}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{user.role}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === "providers" && (
        <div>
          <h2>All Providers</h2>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ backgroundColor: "#f0f0f0" }}>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>User ID</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Verified</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Documents</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Action</th>
              </tr>
            </thead>
            <tbody>
              {providers.map((provider) => (
                <tr key={provider._id}>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{provider.userId}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>
                    {provider.verified ? "✅ Verified" : "❌ Not Verified"}
                  </td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>
                    Aadhar: {provider.documents?.aadhar || "N/A"}<br/>
                    PAN: {provider.documents?.pan || "N/A"}
                  </td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>
                    {!provider.verified && (
                      <button 
                        onClick={() => handleVerifyProvider(provider._id)}
                        style={{ padding: "5px 10px", cursor: "pointer", backgroundColor: "green", color: "white", border: "none" }}
                      >
                        Verify
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <button 
        onClick={() => {
          localStorage.removeItem("token");
          window.location.href = "/";
        }}
        style={{ marginTop: "30px", padding: "10px 20px", cursor: "pointer" }}
      >
        Logout
      </button>
    </div>
  );
}
